package com.primehr.evidence.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.util.Locale;
@Entity @Table(name="evidence_requirement",uniqueConstraints={@UniqueConstraint(name="uk_evidence_requirement_code",columnNames={"agency_id","framework_version_id","normalized_code"}),@UniqueConstraint(name="uk_evidence_requirement_order",columnNames={"agency_id","indicator_id","display_order"})})
public class EvidenceRequirement extends RspAuditedEntity{public enum EvidenceType{LIVE_TRANSACTION,REPORT,DOCUMENT,POLICY,OTHER}@Column(name="framework_version_id",nullable=false,length=36)private String frameworkVersionId;@Column(name="indicator_id",nullable=false,length=36)private String indicatorId;@Column(nullable=false,length=80)private String code;@Column(name="normalized_code",nullable=false,length=80)private String normalizedCode;@Column(nullable=false,length=300)private String title;@Column(name="evidence_guidance",nullable=false,length=4000)private String evidenceGuidance;@Enumerated(EnumType.STRING)@Column(name="evidence_type",nullable=false,length=30)private EvidenceType evidenceType;@Column(name="recurrence_months")private Integer recurrenceMonths;@Column(name="freshness_days")private Integer freshnessDays;@Column(nullable=false)private boolean required;@Column(name="allows_not_applicable",nullable=false)private boolean allowsNotApplicable;@Column(name="display_order",nullable=false)private int displayOrder;protected EvidenceRequirement(){}public EvidenceRequirement(String agency,String framework,String indicator,String code,String title,String guidance,EvidenceType type,Integer recurrence,Integer freshness,boolean required,boolean allowsNa,int order){super(agency);frameworkVersionId=requiredText(framework,"frameworkVersionId");indicatorId=requiredText(indicator,"indicatorId");this.code=requiredText(code,"code");normalizedCode=this.code.toUpperCase(Locale.ROOT);this.title=requiredText(title,"title");evidenceGuidance=requiredText(guidance,"evidenceGuidance");if(type==null)throw new IllegalArgumentException("evidenceType is required");evidenceType=type;if(recurrence!=null&&recurrence<1)throw new IllegalArgumentException("recurrenceMonths must be positive");if(freshness!=null&&freshness<1)throw new IllegalArgumentException("freshnessDays must be positive");if(order<1)throw new IllegalArgumentException("displayOrder must be positive");recurrenceMonths=recurrence;freshnessDays=freshness;this.required=required;allowsNotApplicable=allowsNa;displayOrder=order;}public String getIndicatorId(){return indicatorId;}public String getCode(){return code;}public String getTitle(){return title;}public String getEvidenceGuidance(){return evidenceGuidance;}public EvidenceType getEvidenceType(){return evidenceType;}public Integer getRecurrenceMonths(){return recurrenceMonths;}public Integer getFreshnessDays(){return freshnessDays;}public boolean isRequired(){return required;}public boolean isAllowsNotApplicable(){return allowsNotApplicable;}public int getDisplayOrder(){return displayOrder;}}
